   838  struct config *config_isolate_section(struct config *current_conf,
   839      struct config_line *current_line)
   840  {
   841      struct lexer *lexer;
   842      struct config *isolated;
   843      const char *pos;
   844
   845      if (current_line->type != CONFIG_LINE_TYPE_SECTION)
   846          return NULL;
   847
   848      isolated = malloc(sizeof(*isolated));
   849      if (!isolated)
   850          return NULL;
   851
   852      memcpy(isolated, current_conf, sizeof(*isolated));
   853      lwan_strbuf_init(&isolated->parser.strbuf);
   854
   855      isolated->mapped.addr = NULL;
   856      isolated->mapped.sz = 0;
   857
   858      lexer = &isolated->parser.lexer;
   859      lexer->start = lexer->pos;
   860
   861      pos = isolated->parser.lexer.pos;
   862      if (!find_section_end(isolated)) {
   863          lwan_strbuf_free(&isolated->parser.strbuf);
   864          free(isolated);
   865
   866          config_error(current_conf,
   867              "Could not find section end while trying to isolate");
   868
   869          return NULL;
   870      }
   871
   872      lexer->end = lexer->pos;
   873      lexer->start = lexer->pos = pos;
   874
   875      return isolated;
   876  }
